// Demo data for mock mode (no Supabase credentials). Deterministic: same seed → same data.
// History is generated by running the real progression rule session after session, so the
// hints, PRs and progress charts you see in mock mode behave like they would on real data.
import { computeHrSummary, progressionHint, HR_RETENTION_MS } from './gymLogic'

export function mulberry32(seed) {
  let a = seed >>> 0
  return () => {
    a = (a + 0x6D2B79F5) >>> 0
    let t = a
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

export function hashString(s) {
  let h = 2166136261
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) }
  return h >>> 0
}

let idCounter = 0
export function mockId() {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID()
  idCounter += 1
  return `00000000-0000-4000-8000-${String(Date.now() % 1e8).padStart(8, '0')}${String(idCounter).padStart(4, '0')}`
}

// Synthetic Inspire-3-like HR for a session window, 5 s buckets like heart_rate_intraday:
// work bouts (~45 s, HR climbs) followed by rest (HR decays), with a warm-up ramp.
export function syntheticHr(sessionId, startMs, endMs) {
  const rnd = mulberry32(hashString(sessionId))
  const out = []
  let bpm = 82
  const cycle = 150 + Math.floor(rnd() * 40) // seconds per set + rest
  for (let t = startMs; t <= endMs; t += 5000) {
    const sec = (t - startMs) / 1000
    const warm = Math.min(1, sec / 600)
    const inWork = sec % cycle < 45
    const target = inWork ? 118 + 30 * warm + rnd() * 10 : 96 + 10 * warm
    bpm += (target - bpm) * (inWork ? 0.18 : 0.08) + (rnd() - 0.5) * 3
    out.push({ t, bpm: Math.round(bpm) })
  }
  return out
}

const LIB = {
  pulldown: 'Wide-Grip_Lat_Pulldown',
  shoulder: 'Dumbbell_Shoulder_Press',
  row: 'Seated_Cable_Rows',
  pushdown: 'Triceps_Pushdown',
  curl: 'Dumbbell_Bicep_Curl',
  legpress: 'Leg_Press',
  legcurl: 'Lying_Leg_Curls',
  legext: 'Leg_Extensions',
  calf: 'Seated_Calf_Raise',
  crunch: 'Ab_Crunch_Machine',
}

export function createSeed(nowMs) {
  const rnd = mulberry32(20261102)
  const customId = '7f1d9c2e-0000-4000-8000-000000000001'
  const custom = [{
    id: customId, created_at: new Date(nowMs - 50 * 864e5).toISOString(),
    name: 'Chest press (Gym80 #7)', primary_muscles: ['chest'], secondary_muscles: ['triceps', 'shoulders'],
    equipment: 'machine', category: 'strength', mechanic: 'compound', force: 'push',
    notes: 'Seat height 4, handles middle', based_on: 'Leverage_Chest_Press', archived: false,
  }]
  const chest = 'custom:' + customId

  const routineA = { id: '7f1d9c2e-0000-4000-8000-0000000000a1', name: 'A — Upper', schedule_type: 'rotation', weekdays: [], rotation_order: 0, notes: '', archived: false }
  const routineB = { id: '7f1d9c2e-0000-4000-8000-0000000000b1', name: 'B — Lower', schedule_type: 'rotation', weekdays: [], rotation_order: 1, notes: '', archived: false }
  // ids are assigned right below (deterministic so localStorage-persisted mock data stays stable)
  const mk = (routine, position, exercise_id, o) => ({
    routine_id: routine.id, position, exercise_id,
    target_sets: 3, rep_min: 8, rep_max: 12, start_weight_kg: null, increment_kg: 2.5,
    progression: 'double', rest_seconds: null, notes: '', ...o,
  })
  const exA = [
    mk(routineA, 0, chest, { start_weight_kg: 40, increment_kg: 5 }),
    mk(routineA, 1, LIB.pulldown, { start_weight_kg: 40, increment_kg: 5 }),
    mk(routineA, 2, LIB.shoulder, { start_weight_kg: 12, increment_kg: 2, rep_min: 8, rep_max: 12 }),
    mk(routineA, 3, LIB.row, { start_weight_kg: 35, increment_kg: 5 }),
    mk(routineA, 4, LIB.pushdown, { start_weight_kg: 20, increment_kg: 2.5, rep_min: 10, rep_max: 15, rest_seconds: 60 }),
    mk(routineA, 5, LIB.curl, { start_weight_kg: 10, increment_kg: 2, rep_min: 10, rep_max: 12, rest_seconds: 60 }),
  ].map((e, i) => ({ ...e, id: `7f1d9c2e-0000-4000-8000-0000000a00${String(i).padStart(2, '0')}` }))
  const exB = [
    mk(routineB, 0, LIB.legpress, { start_weight_kg: 80, increment_kg: 10, progression: 'linear', rep_min: 8, rep_max: 8, target_sets: 3, rest_seconds: 150 }),
    mk(routineB, 1, LIB.legcurl, { start_weight_kg: 30, increment_kg: 5 }),
    mk(routineB, 2, LIB.legext, { start_weight_kg: 35, increment_kg: 5 }),
    mk(routineB, 3, LIB.calf, { start_weight_kg: 25, increment_kg: 5, rep_min: 12, rep_max: 15, rest_seconds: 60 }),
    mk(routineB, 4, LIB.crunch, { start_weight_kg: 25, increment_kg: 5, rep_min: 12, rep_max: 15, rest_seconds: 60 }),
  ].map((e, i) => ({ ...e, id: `7f1d9c2e-0000-4000-8000-0000000b00${String(i).padStart(2, '0')}` }))

  const sessions = [], sets = []
  // 12 sessions, A/B alternating, every 3–4 days, last one yesterday evening (inside the 48 h HR window).
  const yesterday = new Date(nowMs - 864e5); yesterday.setHours(18, 10, 0, 0)
  const days = []
  let d = yesterday.getTime()
  for (let i = 0; i < 12; i++) { days.unshift(d); d -= (3 + (i % 2)) * 864e5 }
  days.forEach((startMs, i) => {
    const routine = i % 2 === 0 ? routineA : routineB
    const exs = routine === routineA ? exA : exB
    const sid = `7f1d9c2e-0000-4000-8000-1000000000${String(i).padStart(2, '0')}`
    let t = startMs + 4 * 60000
    for (const ex of exs) {
      const history = sessions
        .map(s => sets.filter(x => x.session_id === s.id && x.exercise_id === ex.exercise_id))
        .filter(a => a.length).reverse()
      const hint = progressionHint(ex, history)
      const w = hint.weight ?? ex.start_weight_kg
      for (let n = 1; n <= ex.target_sets; n++) {
        // Mostly hit the aim, sometimes one more, fatigue on later sets.
        const aim = hint.reps ?? ex.rep_min
        let reps = aim + (rnd() < 0.45 ? 1 : 0) + (rnd() < 0.2 ? 1 : 0) - (n === ex.target_sets && rnd() < 0.35 ? 1 : 0)
        reps = Math.max(ex.rep_min - 1, Math.min(ex.rep_max, reps))
        sets.push({
          id: `7f1d9c2e-0000-4000-8000-2${String(i).padStart(3, '0')}${String(sets.length).padStart(8, '0')}`,
          session_id: sid, exercise_id: ex.exercise_id, set_number: n, weight_kg: w, reps,
          routine_exercise_id: ex.id, swapped_from_exercise_id: null, is_adhoc: false,
          created_at: new Date(t).toISOString(),
        })
        t += (ex.rest_seconds ?? 90) * 1000 + 40000
      }
      t += 60000
    }
    // One ad-hoc extra and one swap for realism.
    if (i === 9) {
      sets.push({ id: mockId(), session_id: sid, exercise_id: 'Plank', set_number: 1, weight_kg: 0, reps: 60, routine_exercise_id: null, swapped_from_exercise_id: null, is_adhoc: true, created_at: new Date(t).toISOString() })
      t += 120000
    }
    const endMs = t
    const startIso = new Date(startMs).toISOString()
    const session = {
      id: sid, routine_id: routine.id, routine_name: routine.name, started_at: startIso,
      ended_at: new Date(endMs).toISOString(), notes: '', created_at: startIso,
    }
    // Sessions 3 and 4 were "logged late" → no HR summary (the 48 h window had passed).
    const hr = i === 3 || i === 4 ? null : computeHrSummary(syntheticHr(sid, startMs, endMs), 185)
    Object.assign(session, hr || emptyHr(), hr ? { hr_computed_at: session.ended_at } : {})
    sessions.push(session)
  })
  // Last B session: the lying leg curl was taken → swapped to the seated leg curl.
  const lastB = sessions[sessions.length - 1]
  sets.filter(s => s.session_id === lastB.id && s.exercise_id === LIB.legcurl).forEach(s => {
    s.exercise_id = 'Seated_Leg_Curl'; s.swapped_from_exercise_id = LIB.legcurl
  })

  return {
    settings: { hr_max: 185, default_rest_seconds: 90, default_increment_kg: 2.5 },
    customs: custom,
    routines: [routineA, routineB].map(r => ({ ...r, created_at: new Date(nowMs - 50 * 864e5).toISOString() })),
    routineExercises: [...exA, ...exB],
    sessions,
    sets,
  }
}

export function emptyHr() {
  return {
    hr_avg: null, hr_max: null, hr_zone1_min: null, hr_zone2_min: null, hr_zone3_min: null,
    hr_zone4_min: null, hr_zone5_min: null, hr_max_ref: null, hr_sample_count: null, hr_computed_at: null,
  }
}

// HR samples the mock "heart_rate_intraday" would return: only inside the 48 h window.
export function mockHrSamples(startIso, endIso, nowMs, seedKey) {
  const s = new Date(startIso).getTime(), e = Math.min(new Date(endIso).getTime(), nowMs)
  const from = Math.max(s, nowMs - HR_RETENTION_MS)
  if (e <= from) return []
  return syntheticHr(seedKey, s, e).filter(p => p.t >= from)
}

export function mockRecovery(nowMs) {
  const rnd = mulberry32(42)
  const out = []
  for (let i = 13; i >= 0; i--) {
    const d = new Date(nowMs - i * 864e5)
    out.push({
      date: `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`,
      resting_hr_bpm: Math.round(58 + rnd() * 5),
      hrv_rmssd: Math.round((38 + rnd() * 12) * 10) / 10,
    })
  }
  return out
}

export function mockWeightEntries(nowMs) {
  const out = []
  for (let i = 40; i >= 0; i -= 4) {
    const d = new Date(nowMs - i * 864e5)
    out.push({ id: 'w' + i, date: `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`, weight_kg: (82.4 - (40 - i) * 0.03).toFixed(1) })
  }
  return out
}
